#!/usr/bin/env python3
"""Task-local helper: build a data storytelling report from European economic
performance data found in the workspace directory.

Steps:
  1. Inventory the workspace for candidate data files (CSV/TSV/JSON/tabular text).
  2. Parse each file into normalized records (entity, period, indicator, value).
  3. Compute headline metrics and trends.
  4. Generate a data storytelling report (Markdown) following the registered
     data-storytelling skill (Hook -> Context -> Discovery -> Insight ->
     Recommendation -> Call to Action) using only numbers found in the data.
"""
import csv
import json
import math
import os
import re
import sys
from collections import OrderedDict, defaultdict
from datetime import datetime

ROOT = os.getcwd()
OUT_PATH = sys.argv[1] if len(sys.argv) > 1 else "european_economic_performance_report.md"

# ---------------------------------------------------------------------------
# 1. Inventory
# ---------------------------------------------------------------------------
CANDIDATE_EXTS = (".csv", ".tsv", ".txt", ".dat", ".json", ".jsonl")


def discover_files(root):
    found = []
    for dirpath, dirnames, filenames in os.walk(root):
        # Skip the hidden .codex skill directory to avoid unrelated content
        dirnames[:] = [d for d in dirnames if not d.startswith(".")]
        for name in filenames:
            if name.lower().endswith(CANDIDATE_EXTS) and not name.startswith("."):
                found.append(os.path.join(dirpath, name))
    return sorted(found)


# ---------------------------------------------------------------------------
# 2. Parsing / normalization
# ---------------------------------------------------------------------------
COUNTRY_HINTS = [
    "austria", "belgium", "bulgaria", "croatia", "cyprus", "czech", "denmark",
    "estonia", "finland", "france", "germany", "greece", "hungary", "ireland",
    "italy", "latvia", "lithuania", "luxembourg", "malta", "netherlands",
    "poland", "portugal", "romania", "slovakia", "slovenia", "spain", "sweden",
    "iceland", "norway", "switzerland", "turkey", "uk", "united kingdom",
    "eu", "europe", "euro area", "eurozone", "albania", "serbia", "montenegro",
    "north macedonia", "bosnia", "ukraine", "moldova", "georgia",
]
YEAR_RE = re.compile(r"(19|20)\d{2}")
PERIOD_HINTS = ("year", "period", "date", "time", "quarter", "q1", "q2", "q3", "q4")


def norm_key(s):
    return re.sub(r"[^a-z0-9]+", " ", str(s).strip().lower())


def looks_numeric(s):
    if s is None:
        return False
    s = str(s).strip().replace(",", "").replace("%", "").replace(" ", "")
    if s in ("", "-", "--", "n/a", "na"):
        return False
    try:
        float(s)
        return True
    except ValueError:
        return False


def to_float(s):
    try:
        return float(str(s).strip().replace(",", "").replace("%", "").replace(" ", ""))
    except (ValueError, AttributeError):
        return None


def find_year(value):
    if isinstance(value, (int, float)):
        y = int(value)
        return y if 1950 <= y <= 2035 else None
    m = YEAR_RE.search(str(value))
    return int(m.group(0)) if m else None


def find_country(value):
    nk = norm_key(value)
    if not nk:
        return None
    if len(nk) > 60 or nk in ("total", "all", "average", "european union - 27 countries"):
        return nk if nk in ("eu", "europe") else None
    for hint in COUNTRY_HINTS:
        if hint == nk or (len(hint) > 3 and hint in nk):
            return nk.title()
    return None


def is_indicator_header(h):
    nk = norm_key(h)
    ind_words = ("gdp", "growth", "inflation", "unemployment", "debt", "deficit",
                 "export", "import", "invest", "product", "consumer", "price",
                 "labor", "labour", "rate", "value", "index", "balance", "output")
    return any(w in nk for w in ind_words)


def parse_csv(path):
    rows = []
    with open(path, "r", encoding="utf-8", errors="replace", newline="") as f:
        sample = f.read(16384)
        f.seek(0)
        try:
            dialect = csv.Sniffer().sniff(sample, delimiters=",;\t|")
        except csv.Error:
            dialect = csv.excel
        reader = csv.reader(f, dialect)
        table = [r for r in reader if any(c.strip() for c in r)]
    if not table:
        return rows
    header = table[0]
    header = [h.strip() for h in header]
    for line in table[1:]:
        if len(line) == len(header):
            rows.append(dict(zip(header, line)))
        else:
            rows.append({header[i] if i < len(header) else f"col{i}": (line[i] if i < len(line) else "")
                         for i in range(max(len(header), len(line)))})
    return rows


def parse_json(path):
    rows = []
    with open(path, "r", encoding="utf-8", errors="replace") as f:
        data = json.load(f)

    def flatten(obj, prefix=""):
        if isinstance(obj, dict):
            flat = {}
            for k, v in obj.items():
                if isinstance(v, (dict, list)):
                    sub = flatten(v, f"{prefix}{k}.")
                    flat.update(sub)
                else:
                    flat[f"{prefix}{k}"] = v
            return flat
        if isinstance(obj, list):
            return {f"{prefix}item{i}": v for i, v in enumerate(obj) if not isinstance(v, (dict, list))}
        return {prefix.rstrip("."): obj}

    if isinstance(data, dict):
        # Maybe {'countries': [...]} or {'data': [...]}
        for k, v in data.items():
            if isinstance(v, list) and v and isinstance(v[0], (dict, list)):
                for item in v:
                    rows.append(flatten(item))
                break
        else:
            rows.append(flatten(data))
    elif isinstance(data, list):
        for item in data:
            if isinstance(item, dict):
                rows.append(flatten(item))
    return rows


def parse_tabular_text(path):
    """Best-effort parse of whitespace/pipe-delimited numeric tables."""
    rows = []
    with open(path, "r", encoding="utf-8", errors="replace") as f:
        lines = [ln.rstrip("\n") for ln in f if ln.strip()]
    if not lines:
        return rows
    header_idx = None
    for i, ln in enumerate(lines[:12]):
        toks = re.split(r"[\t|]+|\s{2,}", ln.strip())
        if len(toks) >= 3 and any(looks_numeric(t) for t in toks):
            header_idx = i
            break
    if header_idx is None:
        return rows
    header = re.split(r"[\t|]+|\s{2,}", lines[header_idx].strip())
    for ln in lines[header_idx + 1:]:
        toks = re.split(r"[\t|]+|\s{2,}", ln.strip())
        if not toks:
            continue
        rec = {}
        for i, h in enumerate(header):
            rec[h] = toks[i] if i < len(toks) else ""
        rows.append(rec)
    return rows


def normalize_record(rec):
    """Map an arbitrary row dict to (entity, year, indicator, value)."""
    out = []
    entity, year, indicator, value = None, None, None, None
    for k, v in rec.items():
        nk = norm_key(k)
        if entity is None:
            entity = find_country(v) or find_country(k)
        if year is None:
            y = find_year(v) if not looks_numeric(v) else None
            if y is None and any(p in nk for p in ("year", "period", "date", "time")):
                y = find_year(v)
            year = y
    if entity is None:
        for k, v in rec.items():
            c = find_country(v)
            if c:
                entity = c
                break
    if year is None:
        for k, v in rec.items():
            y = find_year(v)
            if y:
                year = y
                break
    for k, v in rec.items():
        if v is None or not looks_numeric(v):
            continue
        nk = norm_key(k)
        if nk in ("country", "region", "entity", "geo", "area") or find_country(v):
            continue
        if any(p in nk for p in ("year", "period", "date", "time", "quarter")):
            continue
        fv = to_float(v)
        if fv is None:
            continue
        if entity is None and find_country(k):
            ent = find_country(k)
        else:
            ent = entity
        out.append({
            "entity": ent or "EU",
            "year": year,
            "indicator": k.strip(),
            "value": fv,
            "raw": v,
        })
    return out


def load_all(files):
    records = []
    parsed_files = []
    for path in files:
        try:
            if path.lower().endswith(".json"):
                rows = parse_json(path)
            elif path.lower().endswith((".csv", ".tsv")):
                rows = parse_csv(path)
            else:
                rows = parse_tabular_text(path)
            if not rows:
                continue
            n = 0
            for r in rows:
                for nr in normalize_record(r):
                    records.append(nr)
                    n += 1
            if n:
                parsed_files.append((os.path.relpath(path, ROOT), len(rows), n))
        except Exception as e:  # noqa: BLE001 - inventory must not die on one file
            print(f"[warn] could not parse {path}: {e}", file=sys.stderr)
    return records, parsed_files


# ---------------------------------------------------------------------------
# 3. Analysis helpers
# ---------------------------------------------------------------------------
def pct_change(old, new):
    if old is None or new is None or old == 0:
        return None
    return (new - old) / abs(old) * 100.0


def fmt(v, nd=1):
    if v is None or (isinstance(v, float) and not math.isfinite(v)):
        return "n/a"
    if isinstance(v, float) and v.is_integer():
        return str(int(v))
    return f"{v:.{nd}f}"


def summarize(records):
    by_entity = defaultdict(list)
    for r in records:
        by_entity[r["entity"]].append(r)
    summary = OrderedDict()
    for ent in sorted(by_entity):
        recs = by_entity[ent]
        by_ind = defaultdict(list)
        for r in recs:
            by_ind[r["indicator"]].append(r)
        years = sorted({r["year"] for r in recs if r["year"]})
        first_y = years[0] if years else None
        last_y = years[-1] if years else None
        inds = {}
        for ind, vals in by_ind.items():
            years_sorted = sorted([v for v in vals if v["year"]], key=lambda x: x["year"])
            latest = years_sorted[-1] if years_sorted else None
            earliest = years_sorted[0] if years_sorted else None
            all_vals = [v["value"] for v in vals if v["year"]]
            inds[ind] = {
                "n": len(vals),
                "first_year": earliest["year"] if earliest else None,
                "last_year": latest["year"] if latest else None,
                "first_value": earliest["value"] if earliest else None,
                "last_value": latest["value"] if latest else None,
                "min": min(all_vals) if all_vals else None,
                "max": max(all_vals) if all_vals else None,
                "mean": sum(all_vals) / len(all_vals) if all_vals else None,
                "change": pct_change(earliest["value"] if earliest else None,
                                     latest["value"] if latest else None),
            }
        summary[ent] = {"years": years, "first_year": first_y, "last_year": last_y,
                        "indicators": inds}
    return summary


def pick_main_indicator(summary):
    """Pick the most story-worthy indicator present across entities."""
    counts = defaultdict(int)
    for ent, info in summary.items():
        for ind in info["indicators"]:
            nk = norm_key(ind)
            if any(w in nk for w in ("gdp", "growth", "inflation", "unemployment",
                                     "debt", "deficit", "export", "import")):
                counts[ind] += 1
    if not counts:
        counts = defaultdict(int)
        for ent, info in summary.items():
            for ind in info["indicators"]:
                counts[ind] += 1
    return max(counts, key=lambda k: (counts[k], k))


# ---------------------------------------------------------------------------
# 4. Report generation (data storytelling structure)
# ---------------------------------------------------------------------------
def build_report(summary, main_ind, parsed_files, n_records):
    L = []
    now = datetime.utcnow().strftime("%Y-%m-%d")
    L.append("# European Economic Performance: A Data Story")
    L.append("")
    L.append(f"> Generated {now} from data files in this directory. "
             "All figures below are computed directly from the source data.")
    L.append("")
    L.append("---")
    L.append("")

    # ---- Hook
    hook_num = None
    hook_txt = "The data tells a clear story about Europe's economic trajectory."
    for ent, info in summary.items():
        ind = info["indicators"].get(main_ind)
        if ind and ind["change"] is not None:
            hook_num = ind["change"]
            hook_txt = (f"Across the entities in this dataset, the headline indicator "
                        f"(**{main_ind}**) moved **{fmt(hook_num, 1)}%** between "
                        f"{ind['first_year']} and {ind['last_year']}.")
            break
    L.append("## The Hook")
    L.append("")
    L.append(f"> **{hook_txt}**")
    L.append("")
    L.append("This report turns those numbers into a narrative: where Europe started, "
             "what changed, what the data reveals, and what it implies for the road ahead.")
    L.append("")

    # ---- Context
    L.append("## The Context: Where Europe Started")
    L.append("")
    if summary:
        ents = list(summary.keys())
        years = sorted({y for e in summary.values() for y in e["years"] if y})
        L.append(f"- **{len(ents)} entities/regions** tracked in this dataset.")
        if years:
            L.append(f"- Data spans **{years[0]} to {years[-1]}**.")
        L.append(f"- **{n_records} normalized observations** parsed from "
                 f"{len(parsed_files)} data file(s).")
        L.append("")
        L.append("### Files analyzed")
        L.append("")
        L.append("| File | Rows | Records extracted |")
        L.append("|---|---|---|")
        for p, r, n in parsed_files:
            L.append(f"| `{p}` | {r} | {n} |")
        L.append("")
        # Baseline table
        L.append("### Baseline snapshot")
        L.append("")
        L.append("| Entity | Years covered | Observations | Latest value |")
        L.append("|---|---|---|---|")
        for ent in ents:
            info = summary[ent]
            ind = info["indicators"].get(main_ind)
            latest = f"{fmt(ind['last_value'])} ({ind['last_year']})" if ind and ind["last_value"] is not None else "n/a"
            L.append(f"| {ent} | {info['first_year']}–{info['last_year']} | "
                     f"{sum(len(v) for v in info['indicators'].values())} | {latest} |")
        L.append("")
    else:
        L.append("No structured numeric data could be identified in this directory. "
                 "Add CSV/JSON/tabular files with country, year and indicator columns.")
        L.append("")

    # ---- Conflict / Discovery
    L.append("## The Conflict: Divergence in the Numbers")
    L.append("")
    changes = []
    for ent, info in summary.items():
        ind = info["indicators"].get(main_ind)
        if ind and ind["change"] is not None:
            changes.append((ent, ind["change"], ind["last_value"], ind["last_year"]))
    if changes:
        up = [c for c in changes if c[1] > 0]
        down = [c for c in changes if c[1] < 0]
        L.append("The story is not uniform. When we compare the **latest values** against the "
                 "**earliest values** in this dataset:")
        L.append("")
        L.append("| Entity | Change (%) | Latest value | Year |")
        L.append("|---|---|---|---|")
        for ent, ch, lv, ly in sorted(changes, key=lambda x: x[1], reverse=True):
            L.append(f"| {ent} | {fmt(ch, 1)}% | {fmt(lv)} | {ly} |")
        L.append("")
        if up and down:
            L.append(f"- **{len(up)} entity/entities improved** (median change "
                     f"{fmt(sorted([c[1] for c in up])[len(up)//2], 1)}%).")
            L.append(f"- **{len(down)} entity/entities weakened** (median change "
                     f"{fmt(sorted([c[1] for c in down])[len(down)//2], 1)}%).")
            L.append("- This **divergence is the central tension** of the European story: "
                     "gains in some economies are offset by losses elsewhere.")
        elif up:
            L.append(f"- **All {len(up)} entity/entities moved upward** — a broadly positive picture "
                     "with room to compare the pace of gains.")
        else:
            L.append(f"- **All {len(down)} entity/entities moved downward** — a pressure story "
                     "that raises the stakes for policy and investment choices.")
        L.append("")

    # ---- Insight / Rising action
    L.append("## The Insight: What the Data Reveals")
    L.append("")
    L.append("Digging deeper into the numbers surfaces three patterns:")
    L.append("")
    insights = []
    for ent, info in list(summary.items())[:5]:
        ind = info["indicators"].get(main_ind)
        if ind and ind["change"] is not None:
            insights.append((ent, ind))
    if insights:
        best = max(insights, key=lambda x: x[1]["change"])
        worst = min(insights, key=lambda x: x[1]["change"])
        L.append(f"1. **The standout performer is {best[0]}** — {main_ind} moved "
                 f"from {fmt(best[1]['first_value'])} ({best[1]['first_year']}) to "
                 f"{fmt(best[1]['last_value'])} ({best[1]['last_year']}), a "
                 f"**{fmt(best[1]['change'], 1)}%** swing.")
        L.append(f"2. **The laggard is {worst[0]}** — {main_ind} went from "
                 f"{fmt(worst[1]['first_value'])} ({worst[1]['first_year']}) to "
                 f"{fmt(worst[1]['last_value'])} ({worst[1]['last_year']}), a "
                 f"**{fmt(worst[1]['change'], 1)}%** change.")
        L.append(f"3. **The range of outcomes is wide** — across all entities, "
                 f"the spread between best and worst change is "
                 f"**{fmt(best[1]['change'] - worst[1]['change'], 1)} percentage points**, "
                 "signaling that European performance is shaped by local conditions, not a single trend.")
        L.append("")
        L.append("### Year-by-year movement (headline indicator)")
        L.append("")
        series = defaultdict(dict)
        for ent, info in summary.items():
            ind = info["indicators"].get(main_ind)
            if ind and ind["first_year"] and ind["last_year"]:
                series[ent][ind["first_year"]] = ind["first_value"]
                series[ent][ind["last_year"]] = ind["last_value"]
        all_years = sorted({y for d in series.values() for y in d})
        if len(all_years) >= 2:
            L.append("| Entity | " + " | ".join(str(y) for y in all_years) + " |")
            L.append("|---|" + "---|" * len(all_years))
            for ent in sorted(series):
                L.append(f"| {ent} | " + " | ".join(
                    fmt(series[ent].get(y)) for y in all_years) + " |")
            L.append("")
    L.append("The pattern becomes clear when we stop looking at averages and "
             "compare **who is pulling Europe up** versus **who is holding it back**.")
    L.append("")

    # ---- Resolution / Recommendation
    L.append("## The Resolution: What This Implies")
    L.append("")
    L.append("Based on the observed data:")
    L.append("")
    L.append("1. **Benchmark against the leaders.** The gap between the top and bottom "
             "performers is the single most actionable number in this dataset — closing "
             "even part of it would lift the European average meaningfully.")
    L.append("2. **Watch the direction of travel.** The latest-year values set the baseline "
             "for the next cycle; early signals in the most recent period deserve the "
             "closest monitoring.")
    L.append("3. **Treat the region as a portfolio.** Divergent outcomes mean a "
             "one-size-fits-all read of 'Europe' hides as much as it reveals — "
             "segment the analysis by entity before making decisions.")
    L.append("")

    # ---- Call to action
    L.append("## Call to Action")
    L.append("")
    L.append("**Next steps for the team:**")
    L.append("")
    L.append("- Refresh this dataset with the next reporting period to confirm whether "
             "the trend is accelerating or reversing.")
    L.append("- Build a quarterly scorecard around the headline indicator for each "
             "entity, with flags for the entities whose change exceeds ±5%.")
    L.append("- Review the leaders' latest values as targets, and investigate the "
             "laggards' drivers before the next planning cycle.")
    L.append("")
    L.append("---")
    L.append("")
    L.append("## Appendix: Methodology & Caveats")
    L.append("")
    L.append("- Values were extracted from plain-text data files in this directory "
             "(CSV/TSV/JSON/tabular text) and normalized by entity, year, and indicator.")
    L.append("- Percent changes compare the first and last available year per entity; "
             "intermediate years may be missing from the source files.")
    L.append(f"- Headline indicator selected by coverage across entities: **{main_ind}**.")
    L.append("- Confidence: figures reflect what is recorded in the source files; "
             "gaps or reporting differences between countries are inherited from the data.")
    L.append("")
    return "\n".join(L)


# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------
def main():
    print(f"Workspace root: {ROOT}", flush=True)
    files = discover_files(ROOT)
    print(f"Candidate data files found: {len(files)}", flush=True)
    for f in files:
        print(f"  - {os.path.relpath(f, ROOT)}", flush=True)
    if not files:
        print("ERROR: no candidate data files found in workspace", file=sys.stderr)
        sys.exit(2)

    records, parsed_files = load_all(files)
    print(f"Normalized records: {len(records)}", flush=True)
    if not records:
        print("ERROR: no numeric records could be normalized", file=sys.stderr)
        sys.exit(3)

    summary = summarize(records)
    print(f"Entities identified: {len(summary)} -> {', '.join(summary.keys())}", flush=True)
    main_ind = pick_main_indicator(summary)
    print(f"Headline indicator: {main_ind}", flush=True)

    report = build_report(summary, main_ind, parsed_files, len(records))
    with open(OUT_PATH, "w", encoding="utf-8") as f:
        f.write(report + "\n")
    print(f"Report written: {OUT_PATH} ({len(report)} chars)", flush=True)
    print("=" * 70, flush=True)
    print(report, flush=True)


if __name__ == "__main__":
    main()

