# 4. Report generation (data storytelling structure)
# ---------------------------------------------------------------------------
def build_report(summary, main_ind, parsed_files, n_records):
    L = []
    now = datetime.utcnow().strftime("%Y-%m-%d")
    L.append("# European Economic Performance: A Data Story")
    L.append("")
    L.append(f"> Generated {now} from data files in this directory. "
             "All figures below are computed directly from the source data.")
    L.append("")
    L.append("---")
    L.append("")

    # ---- Hook
    hook_num = None
    hook_txt = "The data tells a clear story about Europe's economic trajectory."
    for ent, info in summary.items():
        ind = info["indicators"].get(main_ind)
        if ind and ind["change"] is not None:
            hook_num = ind["change"]
            hook_txt = (f"Across the entities in this dataset, the headline indicator "
                        f"(**{main_ind}**) moved **{fmt(hook_num, 1)}%** between "
                        f"{ind['first_year']} and {ind['last_year']}.")
            break
    L.append("## The Hook")
    L.append("")
    L.append(f"> **{hook_txt}**")
    L.append("")
    L.append("This report turns those numbers into a narrative: where Europe started, "
             "what changed, what the data reveals, and what it implies for the road ahead.")
    L.append("")

    # ---- Context
    L.append("## The Context: Where Europe Started")
    L.append("")
    if summary:
        ents = list(summary.keys())
        years = sorted({y for e in summary.values() for y in e["years"] if y})
        L.append(f"- **{len(ents)} entities/regions** tracked in this dataset.")
        if years:
            L.append(f"- Data spans **{years[0]} to {years[-1]}**.")
        L.append(f"- **{n_records} normalized observations** parsed from "
                 f"{len(parsed_files)} data file(s).")
        L.append("")
        L.append("### Files analyzed")
        L.append("")
        L.append("| File | Rows | Records extracted |")
        L.append("|---|---|---|")
        for p, r, n in parsed_files:
            L.append(f"| `{p}` | {r} | {n} |")
        L.append("")
        # Baseline table
        L.append("### Baseline snapshot")
        L.append("")
        L.append("| Entity | Years covered | Observations | Latest value |")
        L.append("|---|---|---|---|")
        for ent in ents:
            info = summary[ent]
            ind = info["indicators"].get(main_ind)
            latest = f"{fmt(ind['last_value'])} ({ind['last_year']})" if ind and ind["last_value"] is not None else "n/a"
            L.append(f"| {ent} | {info['first_year']}–{info['last_year']} | "
                     f"{sum(len(v) for v in info['indicators'].values())} | {latest} |")
        L.append("")
    else:
        L.append("No structured numeric data could be identified in this directory. "
                 "Add CSV/JSON/tabular files with country, year and indicator columns.")
        L.append("")

    # ---- Conflict / Discovery
    L.append("## The Conflict: Divergence in the Numbers")
    L.append("")
    changes = []
    for ent, info in summary.items():
        ind = info["indicators"].get(main_ind)
        if ind and ind["change"] is not None:
            changes.append((ent, ind["change"], ind["last_value"], ind["last_year"]))
    if changes:
        up = [c for c in changes if c[1] > 0]
        down = [c for c in changes if c[1] < 0]
        L.append("The story is not uniform. When we compare the **latest values** against the "
                 "**earliest values** in this dataset:")
        L.append("")
        L.append("| Entity | Change (%) | Latest value | Year |")
        L.append("|---|---|---|---|")
        for ent, ch, lv, ly in sorted(changes, key=lambda x: x[1], reverse=True):
            L.append(f"| {ent} | {fmt(ch, 1)}% | {fmt(lv)} | {ly} |")
        L.append("")
        if up and down:
            L.append(f"- **{len(up)} entity/entities improved** (median change "
                     f"{fmt(sorted([c[1] for c in up])[len(up)//2], 1)}%).")
            L.append(f"- **{len(down)} entity/entities weakened** (median change "
                     f"{fmt(sorted([c[1] for c in down])[len(down)//2], 1)}%).")
            L.append("- This **divergence is the central tension** of the European story: "
                     "gains in some economies are offset by losses elsewhere.")
        elif up:
            L.append(f"- **All {len(up)} entity/entities moved upward** — a broadly positive picture "
                     "with room to compare the pace of gains.")
        else:
            L.append(f"- **All {len(down)} entity/entities moved downward** — a pressure story "
                     "that raises the stakes for policy and investment choices.")
        L.append("")

    # ---- Insight / Rising action
    L.append("## The Insight: What the Data Reveals")
    L.append("")
    L.append("Digging deeper into the numbers surfaces three patterns:")
    L.append("")
    insights = []
    for ent, info in list(summary.items())[:5]:
        ind = info["indicators"].get(main_ind)
        if ind and ind["change"] is not None:
            insights.append((ent, ind))
    if insights:
        best = max(insights, key=lambda x: x[1]["change"])
        worst = min(insights, key=lambda x: x[1]["change"])
        L.append(f"1. **The standout performer is {best[0]}** — {main_ind} moved "
                 f"from {fmt(best[1]['first_value'])} ({best[1]['first_year']}) to "
                 f"{fmt(best[1]['last_value'])} ({best[1]['last_year']}), a "
                 f"**{fmt(best[1]['change'], 1)}%** swing.")
        L.append(f"2. **The laggard is {worst[0]}** — {main_ind} went from "
                 f"{fmt(worst[1]['first_value'])} ({worst[1]['first_year']}) to "
                 f"{fmt(worst[1]['last_value'])} ({worst[1]['last_year']}), a "
                 f"**{fmt(worst[1]['change'], 1)}%** change.")
        L.append(f"3. **The range of outcomes is wide** — across all entities, "
                 f"the spread between best and worst change is "
                 f"**{fmt(best[1]['change'] - worst[1]['change'], 1)} percentage points**, "
                 "signaling that European performance is shaped by local conditions, not a single trend.")
        L.append("")
        L.append("### Year-by-year movement (headline indicator)")
        L.append("")
        series = defaultdict(dict)
        for ent, info in summary.items():
            ind = info["indicators"].get(main_ind)
            if ind and ind["first_year"] and ind["last_year"]:
                series[ent][ind["first_year"]] = ind["first_value"]
                series[ent][ind["last_year"]] = ind["last_value"]
        all_years = sorted({y for d in series.values() for y in d})
        if len(all_years) >= 2:
            L.append("| Entity | " + " | ".join(str(y) for y in all_years) + " |")
            L.append("|---|" + "---|" * len(all_years))
            for ent in sorted(series):
                L.append(f"| {ent} | " + " | ".join(
                    fmt(series[ent].get(y)) for y in all_years) + " |")
            L.append("")
    L.append("The pattern becomes clear when we stop looking at averages and "
             "compare **who is pulling Europe up** versus **who is holding it back**.")
    L.append("")

    # ---- Resolution / Recommendation
    L.append("## The Resolution: What This Implies")
    L.append("")
    L.append("Based on the observed data:")
    L.append("")
    L.append("1. **Benchmark against the leaders.** The gap between the top and bottom "
             "performers is the single most actionable number in this dataset — closing "
             "even part of it would lift the European average meaningfully.")
    L.append("2. **Watch the direction of travel.** The latest-year values set the baseline "
             "for the next cycle; early signals in the most recent period deserve the "
             "closest monitoring.")
    L.append("3. **Treat the region as a portfolio.** Divergent outcomes mean a "
             "one-size-fits-all read of 'Europe' hides as much as it reveals — "
             "segment the analysis by entity before making decisions.")
    L.append("")

    # ---- Call to action
    L.append("## Call to Action")
    L.append("")
    L.append("**Next steps for the team:**")
    L.append("")
    L.append("- Refresh this dataset with the next reporting period to confirm whether "
             "the trend is accelerating or reversing.")
    L.append("- Build a quarterly scorecard around the headline indicator for each "
             "entity, with flags for the entities whose change exceeds ±5%.")
    L.append("- Review the leaders' latest values as targets, and investigate the "
             "laggards' drivers before the next planning cycle.")
    L.append("")
    L.append("---")
    L.append("")
    L.append("## Appendix: Methodology & Caveats")
    L.append("")
    L.append("- Values were extracted from plain-text data files in this directory "
             "(CSV/TSV/JSON/tabular text) and normalized by entity, year, and indicator.")
    L.append("- Percent changes compare the first and last available year per entity; "
             "intermediate years may be missing from the source files.")
    L.append(f"- Headline indicator selected by coverage across entities: **{main_ind}**.")
    L.append("- Confidence: figures reflect what is recorded in the source files; "
             "gaps or reporting differences between countries are inherited from the data.")
    L.append("")
    return "\n".join(L)


