# Main
# ---------------------------------------------------------------------------
def main():
    print(f"Workspace root: {ROOT}", flush=True)
    files = discover_files(ROOT)
    print(f"Candidate data files found: {len(files)}", flush=True)
    for f in files:
        print(f"  - {os.path.relpath(f, ROOT)}", flush=True)
    if not files:
        print("ERROR: no candidate data files found in workspace", file=sys.stderr)
        sys.exit(2)

    records, parsed_files = load_all(files)
    print(f"Normalized records: {len(records)}", flush=True)
    if not records:
        print("ERROR: no numeric records could be normalized", file=sys.stderr)
        sys.exit(3)

    summary = summarize(records)
    print(f"Entities identified: {len(summary)} -> {', '.join(summary.keys())}", flush=True)
    main_ind = pick_main_indicator(summary)
    print(f"Headline indicator: {main_ind}", flush=True)

    report = build_report(summary, main_ind, parsed_files, len(records))
    with open(OUT_PATH, "w", encoding="utf-8") as f:
        f.write(report + "\n")
    print(f"Report written: {OUT_PATH} ({len(report)} chars)", flush=True)
    print("=" * 70, flush=True)
    print(report, flush=True)


if __name__ == "__main__":
    main()
